// НЕ ПРОВЕРЕНО В ЖИВОМ БРАУЗЕРЕ: page.route недоступен генератору — шаги написаны строго по плану.
import { test, expect } from '@playwright/test';
import * as path from 'path';
import { suppressMilestoneWindow, dismissMilestoneIfShown } from '../_helpers/milestone';

test.use({ storageState: path.resolve(__dirname, '../../../auth/user1.json') });

test.describe('«המסע שלי»', () => {
  test('JR-01 Промежуточный уровень — 15 молитв (подмена ответа) #6a86f7e8 @prod-safe', async ({ page }) => {
    await suppressMilestoneWindow(page); // окно уровня «עלית דרגה» не должно перекрывать экран
    // 1. До перехода: для GET получить реальный ответ, обрезать массив до 15 записей, вернуть.
    await page.route('**/rest/v1/prayer_completions**', async (route) => {
      if (route.request().method() !== 'GET') {
        await route.continue();
        return;
      }
      const response = await route.fetch();
      let json: unknown;
      try {
        json = await response.json();
      } catch {
        await route.fulfill({ response });
        return;
      }
      await route.fulfill({ response, json: Array.isArray(json) ? json.slice(0, 15) : json });
    });

    // 2. Открыть `/journey`.
    await page.goto('/journey');
    await expect(page.getByText('מתמיד', { exact: true })).toBeVisible({ timeout: 20_000 });
    await dismissMilestoneIfShown(page);
    await expect(page.getByText('5 תפילות לדרגה הבאה')).toBeVisible();
    await expect(page.getByText('דרגה 2 מתוך 10')).toBeVisible();
    await expect(page.getByRole('region', { name: 'סה״כ תפילות: 15' })).toBeVisible();

    // «פילוח תפילות» в сумме 15
    let sum = 0;
    for (const name of ['שחרית', 'מנחה', 'ערבית']) {
      const region = page.getByRole('region', { name: new RegExp(`^${name}: \\d+$`) });
      await expect(region).toBeVisible();
      sum += Number(((await region.getAttribute('aria-label')) ?? '').split(': ')[1]);
    }
    expect(sum).toBe(15);
  });
});
